const ctx = $('Input').first().json;
const userContent = 'Client: ' + ctx.client_name + '\nEntity type: ' + ctx.entity_type + '   State: ' + ctx.state_primary +
'\nHas C-Corp: ' + ctx.has_c_corp + '   PTE election: ' + ctx.has_pte_election +
'\n\n--- PROJECTED FINANCIALS (from QBO) ---\n' + JSON.stringify(ctx.financials ?? {}) +
'\n\n--- OWNER W-2 / WITHHOLDINGS (from pay stubs) ---\n' + JSON.stringify(ctx.payroll ?? {}) +
'\n\n--- PRIOR-YEAR TAX POSITION ---\n' + JSON.stringify(ctx.tax_position ?? {}) +
'\n\nRates: Federal individual per brackets; CA PTE 9.3%; C-corp 21% federal / 8.84% CA. ' +
'CA quarterly schedule 30/40/0/30; Federal 25/25/25/25.';
const payload = {
  model: 'claude-opus-4-8',
  max_tokens: 16000,
  thinking: { type: 'adaptive' },
  system: "You are computing quarterly estimated tax payments for a CPA to review, from a client's projected income and withholdings. Show every input and every step so the preparer can audit the math. Use the provided rates and the state's quarterly schedule. When you must annualize partial-year data, state the factor you used and flag it as a judgment call for the preparer. If the client has a C-corp, also compute the \"with vs. without C-corp\" comparison. Never present the numbers as final \u2014 they are a draft for professional review. Output only the JSON schema.",
  messages: [{ role: 'user', content: userContent }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["projected_income", "projected_net_profit", "annualization_notes", "federal_liability", "state_liability", "total_withholdings", "quarterly_payments", "entity_comparison", "anomalies"], "properties": {"projected_income": {"type": "number"}, "projected_net_profit": {"type": "number"}, "annualization_notes": {"type": "array", "items": {"type": "string"}}, "federal_liability": {"type": "number"}, "state_liability": {"type": "number"}, "total_withholdings": {"type": "number"}, "quarterly_payments": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["quarter", "federal", "state", "due_date"], "properties": {"quarter": {"type": "string"}, "federal": {"type": "number"}, "state": {"type": "number"}, "due_date": {"type": "string"}}}}, "entity_comparison": {"type": "object", "additionalProperties": false, "required": ["applicable", "with_ccorp_total", "without_ccorp_total", "savings"], "properties": {"applicable": {"type": "boolean"}, "with_ccorp_total": {"type": ["number", "null"]}, "without_ccorp_total": {"type": ["number", "null"]}, "savings": {"type": ["number", "null"]}}}, "anomalies": {"type": "array", "items": {"type": "string"}}}} } }
};
return [{ json: { ...$json, payload } }];

// Structured outputs: the JSON arrives as a string in content[0].text.
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
const ctx = $('Input').first().json;
return [{ json: { ...ctx, tax_estimate: out } }];
